// t15_target -- generated by gen_t15_target.py; do not edit by hand.
//
// Every value below comes from compiler/targets/tnca-sim-v0.1.json,
// which is generated from the RTL parameters. This program asserts the
// machine agrees. A compiler trusts that file; nothing else proves it.
.org 0
start:
    // num_roles: how many Role Contexts a partition may use
    s.rdspecial s1, num_roles
    .assert_eq s1, #0x2, #1
    // num_lanes: the vector width every layout is expressed in
    s.rdspecial s1, num_lanes
    .assert_eq s1, #0x10, #2
    // num_vregs: the largest V index one RCTX may name
    s.rdspecial s1, num_vregs
    .assert_eq s1, #0x40, #3
    // num_phys_vregs: the pool a shared window is carved out of
    s.rdspecial s1, num_phys_vregs
    .assert_eq s1, #0x80, #4
    // num_acc: whole-program accumulator allocation
    s.rdspecial s1, num_acc
    .assert_eq s1, #0x10, #5
    // num_barriers: whole-program barrier allocation
    s.rdspecial s1, num_barriers
    .assert_eq s1, #0x20, #6
    // num_windows: concurrent RF windows, so pipeline depth
    s.rdspecial s1, num_windows
    .assert_eq s1, #0x20, #7
    // num_descriptors: live tensor descriptors
    s.rdspecial s1, num_descriptors
    .assert_eq s1, #0x10, #8
    // tensor_max_rank: when a descriptor must be flattened or fall back to the LSU
    s.rdspecial s1, tensor_max_rank
    .assert_eq s1, #0x2, #9
    // cap0: which encodings may be emitted at all
    s.rdspecial s1, cap0
    .assert_eq s1, #0x1e7, #10

    exit
